package server.bots;
import client.Character;import client.Skill;import client.SkillFactory;import constants.skills.Bishop;import org.junit.jupiter.api.Test;import server.StatEffect;import server.maps.*;import java.awt.*;import java.util.List;import java.util.Map;import java.util.Set;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class BotHorntailReviveTest {
 @Test void airborneCorpseUsesReachableCastingPlatformInsteadOfTheFloorDirectlyBelow(){
  var b=mock(Character.class);var map=mock(MapleMap.class);var fx=mock(StatEffect.class);var e=new BotEntry(b,b,null);var corpse=new Point(-2,-136);when(b.getMap()).thenReturn(map);when(b.getPosition()).thenReturn(new Point(0,260));when(map.getAllMonsters()).thenReturn(List.of());when(fx.calculateBoundingBox(any(Point.class),anyBoolean())).thenAnswer(c->{Point p=c.getArgument(0);return new Rectangle(p.x-400,p.y-350,800,600);});
  var ground=new BotNavigationGraph.Region(0,List.of(new BotNavigationGraph.Segment(new Foothold(new Point(-50,260),new Point(50,260),1))));var platform=new BotNavigationGraph.Region(1,List.of(new BotNavigationGraph.Segment(new Foothold(new Point(-374,-160),new Point(-250,-160),2))));var unreachable=new BotNavigationGraph.Region(2,List.of(new BotNavigationGraph.Segment(new Foothold(new Point(-50,-120),new Point(50,-120),3))));
  var graph=spy(new BotNavigationGraph(240060200,1,List.of(ground,platform,unreachable),Map.of(0,ground,1,platform,2,unreachable),Map.of(1,0,2,1,3,2),Map.of(),Set.of()));var origin=b.getPosition();doReturn(0).when(graph).findRegionId(map,origin);doReturn(true).when(graph).canReach(0,0,0);doReturn(true).when(graph).canReach(0,1,0);doReturn(false).when(graph).canReach(0,2,0);
  try(var graphs=mockStatic(BotNavigationGraphProvider.class);var navigation=mockStatic(BotNavigationManager.class);var safety=mockStatic(BotHorntailCombat.class)){graphs.when(()->BotNavigationGraphProvider.peekGraph(map,e.movementProfile)).thenReturn(graph);safety.when(()->BotHorntailCombat.safe(eq(b),any(Point.class),anyList())).thenReturn(true);assertFalse(fx.calculateBoundingBox(b.getPosition(),false).contains(corpse));var point=BotHorntailRevive.stance(e,b,corpse,fx);assertNotNull(point);assertEquals(-160,point.y);assertTrue(fx.calculateBoundingBox(point,false).contains(corpse));assertNotEquals(corpse,point);}
 }
 @Test void anInRangeCorpseUsesTheExistingNormalResurrectionPath(){
  var b=mock(Character.class,RETURNS_DEEP_STUBS);var dead=mock(Character.class,RETURNS_DEEP_STUBS);var map=mock(MapleMap.class);var skill=mock(Skill.class);var fx=mock(StatEffect.class);when(b.getMap()).thenReturn(map);when(dead.getMap()).thenReturn(map);when(b.getParty().getId()).thenReturn(1);when(dead.getParty().getId()).thenReturn(1);when(b.getSkillLevel(Bishop.RESURRECTION)).thenReturn(10);when(skill.getEffect(10)).thenReturn(fx);when(fx.canPaySkillCost(b)).thenReturn(true);when(b.getPosition()).thenReturn(new Point(-374,-160));when(dead.getPosition()).thenReturn(new Point(-2,-136));when(fx.calculateBoundingBox(any(Point.class),anyBoolean())).thenReturn(new Rectangle(-774,-510,800,600));var e=new BotEntry(b,b,null);var crew=List.of(b,dead);
  try(var skills=mockStatic(SkillFactory.class);var normal=mockStatic(BotZakumSupport.class);var walking=mockStatic(BotPinkBeanMovement.class)){skills.when(()->SkillFactory.getSkill(Bishop.RESURRECTION)).thenReturn(skill);normal.when(()->BotZakumSupport.resurrect(e,b,crew,true)).thenReturn(true);assertTrue(BotHorntailRevive.tick(e,b,crew,true));normal.verify(()->BotZakumSupport.resurrect(e,b,crew,true));walking.verifyNoInteractions();when(b.skillIsCooling(Bishop.RESURRECTION)).thenReturn(true);normal.clearInvocations();assertFalse(BotHorntailRevive.tick(e,b,crew,true));normal.verifyNoInteractions();}
 }
}
